import java.util.*;

public class Main {
    void invertedFullPyramid(int n) {
        for (int i = 1; i <= n; i++) {                // row i needs i - 1 spaces then a shrinking star count
            int gap = i - 1;
            int stars = 2 * (n - i + 1) - 1;
            for (int j = 0; j < gap + stars; j++) {     // check every column this row actually uses
                if (j < gap) {
                    System.out.print(" ");                  // still inside the leading gap
                } else {
                    System.out.print("*");                  // inside the star region
                }
            }
            System.out.println();                       // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.invertedFullPyramid(4);
    }
}

